import {spawn,execFileSync} from 'node:child_process';
import fs from 'node:fs';
import crypto from 'node:crypto';
const [label,...command]=process.argv.slice(2),root='test-results/perf12',phase=process.env.PERF_PHASE??'final';
const stdoutPath=`${root}/logs/${phase}-${label}.log`,conditionsPath=`${root}/conditions/${phase}-${label}.jsonl`;
if(!label||!command.length)throw Error('label and command required');
fs.mkdirSync(`${root}/logs`,{recursive:true});fs.mkdirSync(`${root}/conditions`,{recursive:true});
const envKeys=['PERF_ATTEMPT','PERF_PHASE','RELEASE_SLICE','RELEASE_QUALITY','RELEASE_OUT','RELEASE_SECONDS','RELEASE_PERF_ONLY','RELEASE_CPU_PROFILE','RELEASE_SIDES','RELEASE_CANDIDATE_ORIGIN'];
const entry={label,phase,stdoutPath,conditionsPath,started:new Date().toISOString(),revision:execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim(),command:['sh','tools/perf/quiet-run.sh',...command],env:Object.fromEntries(envKeys.filter(k=>process.env[k]!==undefined).map(k=>[k,process.env[k]]))};
const output=fs.createWriteStream(stdoutPath);
const child=spawn(entry.command[0],entry.command.slice(1),{env:{...process.env,PERF_CONDITIONS_LOG:conditionsPath},stdio:['ignore','pipe','pipe']});
for(const [from,to] of [[child.stdout,process.stdout],[child.stderr,process.stderr]])from.on('data',data=>{to.write(data);output.write(data)});
process.on('SIGINT',()=>child.kill('SIGINT'));process.on('SIGTERM',()=>child.kill('SIGTERM'));
const code=await new Promise((resolve,reject)=>{child.on('error',reject);child.on('close',(code,signal)=>{entry.signal=signal;resolve(code)})});
await new Promise(resolve=>output.end(resolve));
entry.finished=new Date().toISOString();entry.seconds=(Date.parse(entry.finished)-Date.parse(entry.started))/1000;entry.exitCode=code;
entry.terminalOutput=fs.readFileSync(stdoutPath,'utf8').trimEnd().split('\n').slice(-12);
entry.stdoutSha256=crypto.createHash('sha256').update(fs.readFileSync(stdoutPath)).digest('hex');
const ledger=`${root}/runs.json`,rows=fs.existsSync(ledger)?JSON.parse(fs.readFileSync(ledger)):[];rows.push(entry);fs.writeFileSync(ledger,JSON.stringify(rows,null,2));
console.log(JSON.stringify({job:label,exitCode:code,seconds:entry.seconds}));process.exitCode=code??1;

