import json, pathlib, hashlib, subprocess, re, math, collections, datetime, copy
R=pathlib.Path('test-results/perf12'); O=pathlib.Path('docs/reports/perf12'); O.mkdir(parents=True,exist_ok=True)
def read(p): return json.loads(pathlib.Path(p).read_text())
def sha(p): return hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
def put(n,x): (O/n).write_text(json.dumps(x,indent=2)+'\n')
def cmd(*args): return subprocess.check_output(args,text=True).strip()
def stats(a): return dict(samples=len(a),p95=sorted(a)[math.ceil(.95*len(a))-1],maximum=max(a),spikes66=sum(x>=66-1e-6 for x in a))
def compare(p,c):
 issues=[]
 if c['p95']>p['p95']+1+1e-6: issues.append('p95 > PROD+1 ms')
 if c['maximum']>p['maximum']+16.8+1e-6: issues.append('max > PROD+1 frame')
 if c['maximum']>=66-1e-6 and p['maximum']<66-1e-6: issues.append('new >=66 ms spike')
 return dict(verdict='FAIL' if issues else 'PASS',issues=issues)
def compact(r,p):
 r=copy.deepcopy(r);r.update(rawSource=str(p),rawSha256=sha(p));r.pop('images',None)
 f=r.get('performance',{});inputs=f.pop('inputs',[])
 r.update(inputFrames=len(inputs),inputSha256=hashlib.sha256(json.dumps(inputs,sort_keys=True,separators=(',',':')).encode()).hexdigest())
 r['samples']=[{k:v for k,v in s.items() if k in ['wallSeconds','scenario','loading','tick','backend','quality','player','alive','alphas','phase','objective','l7Followers','weather','post','car']}for s in r.get('samples',[])]
 # Keep frame intervals, frame clocks, native events, builds and long tasks so verdicts can be independently recomputed.
 for k in ['cpuFrames','layoutCalls','navCalls','frozenBakes']: 
  if not f.get(k):f.pop(k,None)
 return r
loads=[];native=[];extras=[]
for p in sorted((R/'final').glob('*/loads/*.json')):
 for r in read(p):
  r.pop('resources',None);r.pop('frames',None);r.update(rawSource=str(p),rawSha256=sha(p));loads.append(r)
for p in sorted((R/'final').glob('*/strips/webgpu/*.json')):native += [compact(r,p)for r in read(p)]
for p in sorted((R/'extras').glob('*/strips/webgpu/*.json')):extras += [compact(r,p)for r in read(p)]
put('loads.json',loads);put('native.json',native);put('extra-native.json',extras);put('matrix.json',read(R/'summary-final.json'))
extra=[]
for slice,tier in [(s,t)for s in ['r4','r6','approach','drive']for t in ['low','high']]+[('wet','high')]:
 rows={r['side']:r for r in extras if r['slice']==slice and r['tier']==tier}
 row=dict(slice=slice,tier=tier,sides={},coverage={});issues=[]
 for side in ['prod','candidate']:
  r=rows.get(side)
  if not r or not r.get('performance'):issues.append(side+': missing capture');continue
  f=r['performance'];row['sides'][side]=stats(f['frames'])
  if r.get('failure')or r['errors']or r['diagnostic']or f['durationMs']<60000 or sum(f['frames'])<60000 or f['nonGameplayFrames']:issues.append(side+': invalid capture')
  field='car'if slice=='drive'else'player';points=[s[field]for s in r['samples']]
  travel=sum(math.hypot(b['x']-a['x'],b['z']-a['z'])for a,b in zip(points,points[1:]))
  row['coverage'][side]=dict(start=points[0],end=points[-1],sampledPathM=travel,ticks=f['endTick']-f['tick'],wetness=[s.get('weather',{}).get('wetness')for s in r['samples']],ssr=[s.get('post',{}).get('ssr')for s in r['samples']])
  if slice!='wet'and travel<50:issues.append(side+': insufficient native movement')
  if slice=='wet'and any((s.get('weather',{}).get('wetness')or 0)<=.3 for s in r['samples']):issues.append(side+': scene not wet')
  if slice=='wet'and side=='candidate'and not all(s.get('post',{}).get('ssr',{}).get('active')for s in r['samples']):issues.append('candidate: SSR not active')
 if len(row['sides'])==2:issues+=compare(row['sides']['prod'],row['sides']['candidate'])['issues']
 row.update(verdict='perf pending'if len(row['sides'])<2 else'FAIL'if issues else'PASS',issues=issues);extra.append(row)
put('extras.json',extra)
for name in ['runs.json','mirror.json','live-control-final.json','build.json','instrumentation.json','validation.json','ssr-cost.json','attribution12.json','build-before.json','initial-stop.json','source-equivalence.json','validation-before-budget-fix.json','wet-capture-receipt.json','capture-status.json']:
 if(R/name).exists():put(name,read(R/name))
for area,name in [('initial','initial-native.json'),('diagnostic','diagnostic-native.json'),('recheck','rechecks.json')]:
 rows=[compact(r,p)for p in sorted((R/area).glob('*/strips/webgpu/*.json'))for r in read(p)]
 if rows:put(name,rows)
if(R/'summary-initial.json').exists():put('initial-matrix.json',read(R/'summary-initial.json'))
initialLoads=[]
for p in sorted((R/'initial').glob('*/loads/*.json')):
 for r in read(p):
  r.pop('resources',None);r.pop('frames',None);r.update(rawSource=str(p),rawSha256=sha(p));initialLoads.append(r)
put('initial-loads.json',initialLoads)
diagnosticLoads=[]
for p in sorted((R/'causal').glob('*/*/loads/*.json')):
 for r in read(p):
  r.pop('resources',None);r.pop('frames',None)
  tap=r.get('tap',{});sources=tap.pop('shaderSources',[])
  tap['shaderSources']=[dict(id=x['id'],at=x['at'],bytes=len(x['source'].encode()),sha256=hashlib.sha256(x['source'].encode()).hexdigest())for x in sources]
  r.update(rawSource=str(p),rawSha256=sha(p));diagnosticLoads.append(r)
put('diagnostic-loads.json',diagnosticLoads)
conditions=[dict(json.loads(line),source=str(p))for p in sorted((R/'conditions').glob('*.jsonl'))for line in p.read_text().splitlines()if line];put('conditions.json',conditions)
put('host-waits.json',[dict(json.loads(line.split('Host wait before reservation: ',1)[1]),source=str(p))for p in sorted(R.glob('extras-batch*.log'))for line in p.read_text().splitlines()if line.startswith('Host wait before reservation: ')])
mirror=read(R/'mirror.json');bad=[]
for r in mirror['rows']:
 p=R/'prod'/('index.html'if r['path']=='/'else r['path'].lstrip('/'))
 if not p.is_file()or p.stat().st_size!=r['bytes']or sha(p)!=r['sha256']:bad.append(r['path'])
prodBundle=mirror['expectedBundle'];prod=R/'prod/build'/prodBundle;versions=[]
