 if r['level']=='L1'and r['backend']=='webgl2'and r['temperature']=='cold':check(name+'/G-01 Begin mission',r['begin'])
for r in native+extras:
 f=r['performance'];name='/'.join(['native',r['side'],r.get('slice',r['level']),r['tier']]);clock=f['warFrames']or f['chargeFrames']or f['missionFrames']
