  check('/'.join(['moment',m['level'],m['tier'],kind,side]),end<=f['durationMs']and w['startMs']==start and w['endMs']==end and w['indices']==indices and w['stats']==st[side])
 bad=issues(st['prod'],st['candidate']);check('moment/'+m['level']+'/'+m['tier']+'/'+kind+'/verdict',m['sides']==st and m['issues']==bad and m['verdict']==('FAIL'if bad else'PASS'))
