 elif r['label']!='validation'and (r['exitCode']==0 or r.get('phase')=='final'):check('quiet admission/'+r['label'],any(c.get('quiet')is True and c.get('pool')is True and c['source']==r.get('conditionsPath')for c in read('conditions.json')))
