import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';
const report='docs/reports/perf12',root='test-results/perf12',mirror=JSON.parse(fs.readFileSync(report+'/mirror.json')),identity=JSON.parse(fs.readFileSync(report+'/live-control-final.json')),hash=b=>crypto.createHash('sha256').update(b).digest('hex');
const originalIndex=Buffer.from(identity.initialIndexHtml);if(hash(originalIndex)!==identity.initialIndexSha256)throw Error('Stored batch-59 index mismatch');let index=0,restored=0,cached=0;
async function worker(){for(;;){const row=mirror.rows[index++];if(!row)return;const file=path.join(root,'prod',row.path==='/'?'index.html':row.path.slice(1));if(fs.existsSync(file)&&hash(fs.readFileSync(file))===row.sha256){cached++;continue;}let bytes;if(row.path==='/')bytes=originalIndex;else{const response=await fetch(mirror.origin+row.path,{signal:AbortSignal.timeout(45000)});if(!response.ok)throw Error(row.path+' HTTP '+response.status);bytes=Buffer.from(await response.arrayBuffer());}if(bytes.length!==row.bytes||hash(bytes)!==row.sha256)throw Error('Batch-59 bytes unavailable for '+row.path+'; restore an archive matching mirror.json');fs.mkdirSync(path.dirname(file),{recursive:true});fs.writeFileSync(file,bytes);restored++;}}
await Promise.all(Array.from({length:4},worker));fs.writeFileSync(root+'/mirror.json',JSON.stringify({...mirror,restoredAt:new Date().toISOString(),restoredFrom:'Recorded batch-59 ledger and original index; every byte rehashed'},null,2));console.log({files:mirror.rows.length,restored,cached,verified:true});

